mapper.select:
SELECT document_id
FROM rag_documents
WHERE file_hash = #{fileHash}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE c.chunk_id IN
#{chunkId}
AND doc.use_yn = 'Y' AND c.use_yn = 'Y'

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y'
AND doc.document_type IN
#{documentType}
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY CASE
WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 0 WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 1 WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 2
ELSE 3 END, doc.document_type, doc.title, c.sort_order LIMIT #{limit}
